INSERT INTO fin_ar_writeoff (
    ar_id, receipt_id, writeoff_amount, writeoff_date, period,
    dept_id, user_id, create_by, create_time, remark
) VALUES (
    #{arId}, #{receiptId}, #{writeoffAmount}, #{writeoffDate}, #{period},
    #{deptId}, #{userId}, #{createBy}, sysdate(), #{remark}
)

