    dept_id, user_id, create_by, create_time, remark
) VALUES (
    #{provisionNo}, #{period}, #{arId}, #{partnerId}, #{partnerName},
    #{receivableAmount}, #{provisionRatio}, #{provisionAmount}, #{provisionType},
    #{deptId}, #{userId}, #{createBy}, sysdate(), #{remark}
)
